using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Demo6.Game;using Newtonsoft.Json;
public static class V056DirectionCheck {
 public static object Run(){if(!Demo6.Game.PlayerController.Instance||UnityEngine.Object.FindAnyObjectByType<ImportedFxV056>())throw new Exception("Clean live fixture required");bool pause=EditorApplication.isPaused;var records=new List<object>();try{EditorApplication.isPaused=true;for(int i=0;i<8;i++){float a=i*Mathf.PI/4;var normal=new Vector2(Mathf.Cos(a),Mathf.Sin(a));var at=Demo6.Game.PlayerController.Instance.Position+normal;HitEffects.WallDust(at,normal,6);var fx=UnityEngine.Object.FindAnyObjectByType<ImportedFxV056>();var all=new List<ParticleSystem.Particle>();foreach(var ps in fx.GetComponentsInChildren<ParticleSystem>()){var data=new ParticleSystem.Particle[32];int n=ps.GetParticles(data);all.AddRange(data.Take(n));}records.Add(new{degrees=i*45,count=all.Count,onGround=all.All(x=>Mathf.Abs(x.position.z)<.00001f&&Mathf.Abs(x.velocity.z)<.00001f),outward=all.All(x=>Vector2.Dot(x.velocity,normal)>0),maxContactDistance=all.Max(x=>Vector2.Distance(x.position,at))});UnityEngine.Object.DestroyImmediate(fx.gameObject);}}finally{var fx=UnityEngine.Object.FindAnyObjectByType<ImportedFxV056>();if(fx)UnityEngine.Object.DestroyImmediate(fx.gameObject);EditorApplication.isPaused=pause;}File.WriteAllText("검증/v056-fx/directions.json",JsonConvert.SerializeObject(records,Formatting.Indented));return records;}
}
